-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.admin_reopen_reports(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_n integer;
begin
  perform public.require_admin_session();
  if jsonb_typeof(p) is distinct from 'object'
     or (p ->> 'resolution_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'admin_reopen_reports: expected { resolution_id }' using errcode = '22023';
  end if;
  v_id := (p ->> 'resolution_id')::uuid;
  update public.content_reports r set resolution_id = null where r.resolution_id = v_id;
  get diagnostics v_n = row_count;
  delete from public.report_resolutions x where x.id = v_id;
  if not found then
    raise exception 'nothing_to_reopen' using errcode = 'P0002';
  end if;
  return jsonb_build_object('reopened', v_n);
end;
$function$;

grant execute on function public.admin_reopen_reports(p jsonb) to authenticated;
grant execute on function public.admin_reopen_reports(p jsonb) to service_role;
